mapper.select:
        select
        mn.*
        from Sys_Portal_Design mn
        
            
                and mn.Pd_Type=#{params.pdType}
            
            
                and mn.Pd_State=#{params.pdState}
            
            
                and mn.T_Id=#{params.tId}
            
            
                and INSTR(mn.Pd_Create_Nmae,#{params.pdCreateNmae})
            
            
                and INSTR(mn.Pd_Code,#{params.pdCode})
            

            
                and INSTR(mn.Pd_Name,#{params.pdName})
            
        
        
            
                order by mn.${params.sortFiled} ${params.sortType}
            
            
                order by ${params.sortSideFiled} ${params.sortType}
            
            
                order by mn.Pd_Create_Time desc
